<script lang="ts">
 import{onMount}from'svelte';import{marked}from'marked';import DOMPurify from'dompurify';import{getV6Experiment,getV6Reports,getV6ResearchDoc,getV6ResearchRegistry,getV6RunDetail,getV6Runs,getV6Status,v6ReportHtmlUrl,type V6Experiment,type V6PreregEntry,type V6ReportEntry,type V6Reports,type V6ResearchRegistry,type V6RunDetail,type V6Runs,type V6Status}from'../v6Api';let status=$state<V6Status|null>(null);let experiment=$state<V6Experiment|null>(null);let runs=$state<V6Runs|null>(null);let detail=$state<V6RunDetail|null>(null);let reports=$state<V6Reports|null>(null);let registry=$state<V6ResearchRegistry|null>(null);let viewer=$state<V6ReportEntry|null>(null);let docName=$state<string|null>(null);let docHtml=$state<string>('');let docLoading=$state(false);let error=$state<string|null>(null);let loading=$state(true);let copyMessage=$state<string|null>(null);
 const text=(v:unknown)=>v===undefined||v===null||v===''?'MISSING':String(v);const newest=()=>runs?.runs?.[0];const dataset=()=>runs?.datasets?.find(x=>x.run_id===newest()?.dataset_run_id);const verdict=()=>detail?.manifest?.verdict_candidate??newest()?.verdict_candidate;const short=(v:unknown)=>text(v).slice(0,12);const kb=(v:number|undefined)=>typeof v==='number'?`${(v/1024).toFixed(0)} KB`:'MISSING';const badgeClass=(v:string|undefined)=>v==='NO_GO'?'danger':v==='INCONCLUSIVE'?'warn':v?.startsWith('GO_CANDIDATE')?'warn':'muted';const reportUrl=(r:V6ReportEntry,download=false)=>v6ReportHtmlUrl(r.dataset_run_id??'',r.train_run_id??'',download);const preregDoc=(p:V6PreregEntry)=>p.doc;async function copy(value:unknown){try{await navigator.clipboard.writeText(text(value));copyMessage='SHA를 클립보드에 복사했습니다.'}catch{copyMessage='클립보드를 사용할 수 없습니다. SHA를 직접 복사하세요.'}}async function openDoc(name:string|undefined){if(!name)return;docName=name;docHtml='';docLoading=true;const r=await getV6ResearchDoc(name);docLoading=false;if(r.ok&&r.data?.content!==undefined){const raw=r.data.format==='json'?'```json\n'+r.data.content+'\n```':r.data.content;docHtml=DOMPurify.sanitize(await marked.parse(raw));}else{docHtml='<p>문서를 불러오지 못했습니다.</p>';}}async function load(){loading=true;error=null;const[a,b,c,e,g]=await Promise.all([getV6Status(),getV6Experiment(),getV6Runs(),getV6Reports(),getV6ResearchRegistry()]);if(e.ok&&e.data)reports=e.data;if(g.ok&&g.data)registry=g.data;if(a.ok&&a.data&&b.ok&&b.data&&c.ok&&c.data){status=a.data;experiment=b.data;runs=c.data;const r=c.data.runs?.[0];if(r?.dataset_run_id&&r.run_id){const d=await getV6RunDetail(r.dataset_run_id,r.run_id);if(d.ok&&d.data)detail=d.data;else error=d.error??'최신 실행 상세를 불러오지 못했습니다.'}}else error=a.error??b.error??c.error??'알 수 없는 오류가 발생했습니다.';loading=false}onMount(load);
</script>
<section class="page"><header><p class="eyebrow">RESEARCH PROVENANCE</p><h1>보고서</h1><p>판정과 근거의 연결만 기록합니다. 이 화면은 투자 권유나 수익 주장이 아닙니다.</p></header>{#if loading}<section class="panel">판정과 증거 체인을 확인하고 있습니다.</section>{:else if error&&!status}<section class="panel error">{error}</section>{:else}<section class:danger={text(verdict()?.value)==='NO_GO'} class="verdict"><p class="eyebrow">현재 판정</p><h2>{text(verdict()?.value)}</h2>{#each (verdict()?.reasons??[]) as reason}<p>{text(reason)}</p>{:else}<p>판정 사유가 기록되지 않았습니다.</p>{/each}</section>
<section class="card catalog"><h2>연구 보고서 카탈로그 <span class="chip">{reports?.reports?.length ?? 0}건</span></h2><p class="note">실행별 self-contained HTML 보고서입니다. 판정 토큰은 원문 그대로이며 SHA 불일치 보고서는 열람이 차단됩니다.</p>{#if reports?.reports?.length}<div class="report-grid">{#each reports.reports as r}<article class="report-card" class:mismatch={r.integrity!=='OK'}><span class="badge {badgeClass(r.verdict)}">{text(r.verdict)}</span><h3>{text(r.dataset_run_id)}</h3><p class="run">{text(r.train_run_id)}</p><dl><dt>생성</dt><dd>{text(r.generated_utc)}</dd><dt>test OOS</dt><dd>{text(r.test_state)}</dd><dt>지수 절</dt><dd>{text(r.index_overlay_state)}</dd><dt>SHA</dt><dd><code title={text(r.report_sha256)}>{short(r.report_sha256)}…</code><button class="mini" onclick={()=>copy(r.report_sha256)}>복사</button></dd><dt>크기·무결성</dt><dd>{kb(r.size_bytes)} · {text(r.integrity)}</dd></dl>{#if r.integrity==='OK'}<div class="actions"><button onclick={()=>{viewer=viewer===r?null:r}}>{viewer===r?'뷰어 닫기':'보고서 보기'}</button><a href={reportUrl(r)} target="_blank" rel="noopener">새 창</a><a href={reportUrl(r,true)}>다운로드</a></div>{:else}<p class="mismatch-note">SHA_MISMATCH · 열람 차단됨(재생성 필요)</p>{/if}</article>{/each}</div>{#if viewer}<div class="viewer-head"><h3>{text(viewer.dataset_run_id)} / {text(viewer.train_run_id)}</h3><button onclick={()=>{viewer=null}}>닫기</button></div><iframe class="viewer" sandbox="" src={reportUrl(viewer)} title="연구 실행 보고서 뷰어"></iframe>{/if}{:else}<p>생성된 보고서가 없습니다. 실행 종료 후 <code>py -3.11 -m stom_rl.v7_report_builder &lt;run_dir&gt;</code>로 생성합니다.</p>{/if}</section>
<section class="card registry"><h2>연구 레지스트리 <span class="chip">{registry?.preregistrations?.length ?? 0} 사전등록</span></h2><p class="note">사전등록 → 실행 → 판정 → 보고서 생명주기를 한 곳에서 관리합니다. 판정 토큰은 원문 그대로입니다.</p>{#if registry?.preregistrations?.length}<div class="prereg-grid">{#each registry.preregistrations as p}<article class="prereg-card"><div class="prereg-head"><span class="status {p.status==='FROZEN'?'ok':'warn'}">{text(p.status)}</span>{#each (p.verdicts??[]) as v}<span class="badge {badgeClass(v)}">{text(v)}</span>{/each}</div><h3>{text(p.prereg_id)}</h3><p class="fam">{text(p.family)} · 실행 {p.run_count ?? 0}건 · 동결 {text(p.frozen_utc)}</p>{#if p.supersedes}<p class="sup">대체: {text(p.supersedes)}</p>{/if}<div class="prereg-runs">{#each (p.runs??[]) as run}<span class="run-chip {badgeClass(run.verdict)}" title={`${text(run.dataset_run_id)} / ${text(run.train_run_id)} · test ${text(run.test_state)}`}>{text(run.verdict)}{#if run.has_report} ▪ 보고서{/if}</span>{:else}<span class="run-chip muted">실행 없음</span>{/each}</div><div class="actions"><button onclick={()=>openDoc(preregDoc(p))}>사전등록 문서</button><button class="mini" onclick={()=>copy(p.sha256)}>SHA 복사</button></div></article>{/each}</div>{:else}<p>사전등록 문서가 없습니다.</p>{/if}{#if (registry?.result_docs?.length)}<h3 class="docs-title">결과·계획 문서 <span class="chip">{registry.result_docs.length}건</span></h3><div class="doc-links">{#each registry.result_docs as d}<button class="doc-link" onclick={()=>openDoc(d.doc)}>{text(d.doc)}</button>{/each}</div>{/if}{#if docName}<div class="viewer-head"><h3>{text(docName)}</h3><button onclick={()=>{docName=null;docHtml=''}}>닫기</button></div>{#if docLoading}<p class="note">문서를 불러오는 중…</p>{:else}<article class="doc-body">{@html docHtml}</article>{/if}{/if}</section>
{#if runs?.runs?.length}<section class="chains"><section class="chain"><h2>Universe manifest</h2><code title={text(status?.journey.data.universe_manifest)}>{short(status?.journey.data.universe_manifest)}</code><button onclick={()=>copy(status?.journey.data.universe_manifest)}>복사</button><p>{text(status?.journey.data.universe_size)} rows</p></section><section class="chain"><h2>Preregistration</h2><code title={text(experiment?.prereg?.sha256)}>{short(experiment?.prereg?.sha256)}</code><button onclick={()=>copy(experiment?.prereg?.sha256)}>복사</button></section><section class="chain"><h2>Dataset run</h2><code title={text(dataset()?.sha256)}>{short(dataset()?.sha256)}</code><button onclick={()=>copy(dataset()?.sha256)}>복사</button><p>{text(dataset()?.run_id)}</p></section><section class="chain"><h2>Training manifest</h2><code title={text(detail?.manifest_sha256)}>{short(detail?.manifest_sha256)}</code><button onclick={()=>copy(detail?.manifest_sha256)}>복사</button><p>{text(newest()?.run_id)}</p></section></section>{:else}<section class="panel empty"><h2>증거 체인이 비어 있습니다</h2><p>학습 실행이 없으므로 데이터셋·학습 manifest·판정을 연결할 수 없습니다.</p></section>{/if}{#if copyMessage}<p class="copy-message">{copyMessage}</p>{/if}<section class="card rules"><h2>보고 규칙</h2><p>GO/NO-GO/INCONCLUSIVE/NOT_RUN은 그대로 기록되며 완화되지 않습니다.</p></section><section class="card"><h2>관련 문서</h2><div class="docs"><code>requirements.txt</code><code>docs/kronos_v6_prereg_h1_2026-07-19.json</code><code>docs/kronos_v6_universe_manifest_2026-07-19.json</code><code>docs/kronos_v6_goal_review_and_plan_2026-07-19.md</code></div></section>{/if}</section>
<style>.page{width:100%;color:var(--fg)}header,.panel,.card,.verdict{border:1px solid var(--border);border-radius:14px;padding:clamp(16px,4vw,28px);background:var(--surface)}.eyebrow{margin:0;color:var(--accent);font-size:.82rem;font-weight:800;letter-spacing:.1em}h1{margin:7px 0;color:var(--fg-strong);font-size:clamp(1.8rem,6vw,2.6rem)}h2{margin:0 0 12px;color:var(--fg-strong);font-size:1.15rem}.verdict,.card,.panel,.chains{margin-top:16px}.verdict h2{color:var(--info);font-size:clamp(2rem,8vw,3.5rem)}.verdict.danger{border-color:var(--danger);background:var(--danger-soft)}.verdict.danger h2,.error{color:var(--danger)}.chains{display:grid;grid-template-columns:repeat(auto-fit,minmax(420px,1fr));gap:16px}.chain{border:1px solid var(--border-strong);border-radius:10px;padding:16px;background:var(--surface-raised)}code{overflow-wrap:anywhere;color:var(--accent-strong);font-size:.85rem}.chain button{margin-left:8px}.chain p{color:var(--muted)}.rules,.empty{border-color:var(--warn);background:var(--warn-soft);color:var(--warn)}.docs{display:flex;flex-wrap:wrap;gap:8px}.docs code{border:1px solid var(--border-strong);border-radius:999px;padding:5px 8px;background:var(--surface-sunken)}button{border:1px solid var(--accent);border-radius:6px;padding:6px 10px;background:transparent;color:var(--accent-strong);font:inherit;cursor:pointer}.copy-message{color:var(--accent-strong)}
.catalog .chip{display:inline-block;border:1px solid var(--accent);border-radius:999px;margin-left:8px;padding:2px 9px;color:var(--accent-strong);font-size:.76rem;vertical-align:middle}.note{color:var(--muted);font-size:.9rem}.report-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(340px,1fr));gap:14px;margin-top:12px}.report-card{border:1px solid var(--border-strong);border-radius:10px;padding:16px;background:var(--surface-raised)}.report-card.mismatch{border-color:var(--danger);background:var(--danger-soft)}.report-card h3{margin:10px 0 2px;color:var(--fg-strong);font-size:1rem;overflow-wrap:anywhere}.report-card .run{margin:0 0 10px;color:var(--muted);font-size:.84rem;overflow-wrap:anywhere}.badge{display:inline-block;border-radius:999px;padding:4px 12px;font-size:.8rem;font-weight:900;letter-spacing:.04em}.badge.danger{background:var(--danger);color:#fff}.badge.warn{background:var(--warn);color:#1c1917}.badge.muted{background:var(--surface-hover,#64748b);color:var(--fg-strong)}.report-card dl{display:grid;grid-template-columns:auto 1fr;gap:5px 12px;margin:0;font-size:.84rem}.report-card dt{color:var(--muted)}.report-card dd{margin:0;overflow-wrap:anywhere}.mini{margin-left:6px;padding:1px 7px;font-size:.74rem}.actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}.actions a{border:1px solid var(--border-strong);border-radius:6px;padding:6px 10px;color:var(--fg);text-decoration:none;font-size:.88rem}.mismatch-note{margin-top:10px;color:var(--danger);font-weight:700}.viewer-head{display:flex;align-items:center;justify-content:space-between;margin-top:16px}.viewer-head h3{margin:0;color:var(--fg-strong)}.viewer{width:100%;height:min(1400px,85vh);margin-top:8px;border:1px solid var(--border-strong);border-radius:10px;background:#fff}
.registry .chip{display:inline-block;border:1px solid var(--accent);border-radius:999px;margin-left:8px;padding:2px 9px;color:var(--accent-strong);font-size:.76rem;vertical-align:middle}.prereg-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(380px,1fr));gap:14px;margin-top:12px}.prereg-card{border:1px solid var(--border-strong);border-radius:10px;padding:16px;background:var(--surface-raised)}.prereg-head{display:flex;flex-wrap:wrap;align-items:center;gap:6px}.prereg-card h3{margin:10px 0 2px;color:var(--fg-strong);font-size:.98rem;overflow-wrap:anywhere}.prereg-card .fam{margin:0 0 8px;color:var(--muted);font-size:.82rem}.prereg-card .sup{margin:0 0 8px;color:var(--warn);font-size:.78rem}.status{border:1px solid currentColor;border-radius:999px;padding:2px 8px;font-size:.72rem;font-weight:800}.status.ok{color:var(--success)}.status.warn{color:var(--warn)}.prereg-runs{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:10px}.run-chip{border:1px solid currentColor;border-radius:6px;padding:2px 7px;font-size:.72rem;font-weight:700}.run-chip.danger{color:var(--danger)}.run-chip.warn{color:var(--warn)}.run-chip.muted{color:var(--muted)}.docs-title{margin:18px 0 8px;font-size:1rem}.doc-links{display:flex;flex-wrap:wrap;gap:8px}.doc-link{border:1px solid var(--border-strong);border-radius:999px;padding:6px 11px;background:var(--surface-sunken);color:var(--accent-strong);font-size:.82rem}.doc-body{display:block;margin-top:12px;border:1px solid var(--border-strong);border-radius:10px;padding:clamp(16px,3vw,28px);background:var(--surface-sunken);max-height:80vh;overflow:auto;line-height:1.6}.doc-body :global(h1){font-size:1.5rem;color:var(--fg-strong);margin:0 0 12px}.doc-body :global(h2){font-size:1.2rem;color:var(--fg-strong);border-bottom:1px solid var(--border);padding-bottom:6px;margin:20px 0 10px}.doc-body :global(h3){font-size:1.05rem;color:var(--fg-strong);margin:16px 0 8px}.doc-body :global(table){width:100%;border-collapse:collapse;margin:10px 0;font-size:.86rem}.doc-body :global(th),.doc-body :global(td){border:1px solid var(--border);padding:6px 9px;text-align:left}.doc-body :global(th){background:var(--surface-raised);color:var(--muted)}.doc-body :global(code){background:var(--surface-raised);border-radius:4px;padding:1px 5px;font-size:.85rem}.doc-body :global(pre){background:var(--surface-raised);border-radius:8px;padding:12px;overflow:auto}.doc-body :global(blockquote){border-left:3px solid var(--accent);margin:10px 0;padding:4px 14px;color:var(--muted)}.doc-body :global(a){color:var(--accent-strong)}</style>
